        file: "content/knowledge/interviews/011-tobi-l-tke-21-years-of-building-shopify.md",
        title: "Tobi Lütke: 21 Years of Building Shopify",
        show: "David Senra Interview Show",
        subject: "Tobi Lütke",
        sourceBook: "Shopify",
